import json
import logging
from typing import Any
import urllib.parse

from nat.builder.builder import Builder
from nat.builder.framework_enum import LLMFrameworkEnum
from nat.builder.function_info import FunctionInfo
from nat.cli.register_workflow import register_function
from nat.data_models.component_ref import FunctionRef
from nat.data_models.function import FunctionBaseConfig
from pydantic import BaseModel
from pydantic import Field

logger = logging.getLogger(__name__)


class VSTVideoURLConfig(FunctionBaseConfig, name="vst_video_url"):
    """Configuration for the VST Video URL tool."""

    get_video_storage_url_tool: FunctionRef = Field(
        "vst_get_video_storage_url",
        description="The name of the MCP tool to call for getting video storage URLs",
    )
    get_sensor_list_tool: FunctionRef = Field(
        "vst_sensor_list",
        description="The name of the MCP tool to call for getting sensor list",
    )
    vst_external_url: str | None = Field(
        None,
        description="The external VST URL for client-facing URLs (replaces base URL in MCP response)",
    )
    expiry_minutes: str | None = Field(
        None,
        description="Optional expiration time in minutes as string containing positive number (default: 10080 - 7 days)",
    )
    container: str = Field(
        "mp4",
        description="Video container format (default: mp4)",
    )
    overlay_config: bool = Field(
        False,
        description="Whether to enable overlay configuration for object detection overlays",
    )


class VSTVideoURLInput(BaseModel):
    """Input for the VST Video URL tool"""

    sensor_id: str = Field(
        ...,
        description="The stream ID to get video URL for",
        min_length=1,
    )
    start_time: str = Field(
        ...,
        description="The start time in ISO 8601 UTC format (e.g., '2025-08-25T03:05:55.752Z')",
        min_length=1,
    )
    end_time: str = Field(
        ...,
        description="The end time in ISO 8601 UTC format (e.g., '2025-08-25T03:06:15.752Z')",
        min_length=1,
    )
    object_ids: list[str] | None = Field(
        None,
        description="Optional list of object IDs to display as overlays in the video (e.g., from incident objectIds or info.primaryObjectId)",
    )


class VSTVideoURLOutput(BaseModel):
    """Output for the VST Video URL tool"""

    video_url: str = Field(
        ...,
        description="Direct URL to access the video file",
    )
    stream_id: str = Field(
        ...,
        description="The stream ID that is mapped from the sensor ID",
    )
    video_metadata: dict[str, Any] = Field(
        ...,
        description="Metadata returned by the MCP get_video_storage_url tool",
    )


@register_function(config_type=VSTVideoURLConfig, framework_wrappers=[LLMFrameworkEnum.LANGCHAIN])
async def vst_video_url(config: VSTVideoURLConfig, builder: Builder):
    """
    VST Video URL tool that gets video storage URLs from a specific stream using VST MCP.

    This tool uses the MCP get_video_storage_url tool to retrieve temporary URLs
    for accessing stored video files for a specific stream and time range.
    """

    # get the list of sensors
    sensor_list_tool = await builder.get_tool(config.get_sensor_list_tool, wrapper_type=LLMFrameworkEnum.LANGCHAIN)
    if not sensor_list_tool:
        raise ValueError(
            f"Failed to get MCP tool '{config.get_sensor_list_tool}'. Make sure it's configured in your workflow."
        )

    get_video_storage_url_tool = await builder.get_tool(
        config.get_video_storage_url_tool, wrapper_type=LLMFrameworkEnum.LANGCHAIN
    )
    if not get_video_storage_url_tool:
        raise ValueError(
            f"Failed to get MCP tool '{config.get_video_storage_url_tool}'. Make sure it's configured in your workflow."
        )

    async def _vst_video_url(vst_video_url_input: VSTVideoURLInput) -> VSTVideoURLOutput:
        """
        Get a video storage URL for a specific stream and time range.

        Args:
            vst_video_url_input: VSTVideoURLInput containing sensor_id, start_time, end_time, etc.

        Returns:
            VSTVideoURLOutput containing video URL and metadata
        """

        sensor_id_2_vst_stream_id_map = {}

        try:
            sensors_str = await sensor_list_tool.ainvoke(input={})
            if sensors_str:
                # Parse the sensor list response
                text = sensors_str.strip()
                if text and text[0] == text[-1] and text[0] in ('"', "'"):
                    text = text[1:-1]

                sensors_data = json.loads(text)

                # VST returns dictionary where keys are sensor IDs and values are sensor objects
                if isinstance(sensors_data, dict):
                    for sensor_info in sensors_data.values():
                        if isinstance(sensor_info, dict):
                            name = sensor_info.get("name")
                            sensor_id = sensor_info.get("sensorId")
                            if name and sensor_id:
                                sensor_id_2_vst_stream_id_map[name] = sensor_id

                logger.debug(f"sensor_id_2_vst_stream_id_map initialized ==> {sensor_id_2_vst_stream_id_map}")
            else:
                raise ValueError(
                    f"sensor list is empty.  Make sure the sensor {vst_video_url_input.sensor_id} exist in VST"
                )

            stream_id = sensor_id_2_vst_stream_id_map.get(vst_video_url_input.sensor_id, None)
            if not stream_id:
                raise KeyError(
                    f"stream_id not found for sensor {vst_video_url_input.sensor_id}.  Existing sensors are: {sensor_id_2_vst_stream_id_map}"
                )

            logger.info(
                f"Getting video URL for sensor {vst_video_url_input.sensor_id} (VST stream ID: {stream_id}) from {vst_video_url_input.start_time} to {vst_video_url_input.end_time}"
            )

            # Prepare arguments for the MCP tool
            mcp_args = {
                "stream_id": stream_id,
                "start_time": vst_video_url_input.start_time,
                "end_time": vst_video_url_input.end_time,
                "expiry_minutes": "1440",
                "container": "mp4",
            }

            if config.overlay_config:
                # Use provided object_ids or empty list if not provided
                overlay_object_ids = vst_video_url_input.object_ids if vst_video_url_input.object_ids else []
                logger.info(f"Using overlay configuration with object IDs: {overlay_object_ids}")

                # Double-encode to prevent LangChain from parsing the JSON string back into a dict
                config_dict = {
                    "disableAudio": "true",
                    "overlay": {
                        "bbox": {"showAll": not overlay_object_ids, "objectId": overlay_object_ids},
                        "color": "green",
                        "thickness": 5,
                        "debug": True,
                        "opacity": 254,
                    },
                }
                mcp_args["configuration"] = json.dumps(json.dumps(config_dict))

            if config.expiry_minutes:
                mcp_args["expiry_minutes"] = config.expiry_minutes

            if config.container:
                mcp_args["container"] = config.container

            mcp_result = await get_video_storage_url_tool.ainvoke(input=mcp_args)

            logger.debug(f"MCP result being received: {mcp_result}")

            if not mcp_result:
                raise ValueError("MCP tool returned empty result")

            # Initialize variables
            video_url = ""
            video_metadata = {}
            try:
                result = json.loads(mcp_result)

                if "error" in result:
                    raise ValueError(f"MCP server returned error: {result['error']}")

                video_url = result.get("videoUrl", "")
                resource_path = result.get("resourcePath")  # New field from VST API

                if config.vst_external_url:
                    # Replace internal URL with external URL for client access
                    video_url = f"{config.vst_external_url}{urllib.parse.urlparse(video_url).path}"

                if not video_url:
                    raise ValueError("No videoUrl found in MCP response")

                # Translate URL: replace INTERNAL_IP with EXTERNAL_IP for cloud deployments

                video_metadata = {
                    "absolutePath": result.get("absolutePath", ""),
                    "baseUrl": result.get("baseUrl", ""),
                    "fileName": result.get("fileName", ""),
                    "expiryISO": result.get("expiryISO", ""),
                    "expiryTimestamp": result.get("expiryTimestamp", ""),
                    "expiryMinutes": result.get("expiryMinutes", 2),
                }

            except Exception as e:
                raise ValueError(f"Error parsing MCP result: {e}") from e

            logger.info(f"Successfully retrieved video URL: {video_url}")

            return VSTVideoURLOutput(
                video_url=video_url,
                stream_id=stream_id,
                video_metadata=video_metadata,
            )

        except Exception as e:
            logger.error(f"Error getting VST video URL: {e}")
            raise

    yield FunctionInfo.create(
        single_fn=_vst_video_url,
        description=_vst_video_url.__doc__,
        input_schema=VSTVideoURLInput,
        single_output_schema=VSTVideoURLOutput,
    )
